entries[133543] = { ["name"] = "Zügel des ewigen Zeithäschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren ewigen Zeithäscher oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese launischen und wilden Drachen gleiten willkürlich durch den Strom der Zeit, bis sie einen würdigen Reiter finden.\"\nWeltereignis:\nZeitwanderungsdungeons" }
