entries[133595] = { ["name"] = "Gronnzahnkriegshorn", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Gewährt eine Chance, bei einem Nahkampfangriff 'Dämonenschrecken' auszulösen. Erhöht 15 Sek. lang Eure Stärke um 28 und jeglichen Schaden gegen Dämonen um 10%. Wenn Ihr dabei einem Gegner einen Todesstoß versetzt, wird die Dauer um 8 Sek. erhöht (maximal bis zur ursprünglichen Dauer).\n44 ( 44)\n\nBosse mythischer Dungeons von Warlords of Draenor" }
entries[133596] = { ["name"] = "Kugel der Leerensicht", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+11 Intelligenz\nAnlegen: Gewährt bei einem Treffer mit einem Schadenszauber eine Chance, 'Leerensicht' auszulösen. Erhöht kritischen Trefferwert, Tempo und Meisterschaft um 22 und erhöht 15 Sek. lang jeglichen Schaden gegen Dämonen um 10%.\n44 ( 44)\n\nBosse mythischer Dungeons von Warlords of Draenor" }
entries[133597] = { ["name"] = "Unfehlbare Spurensucherkette", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+11 Beweglichkeit\nAnlegen: Gewährt bei Nah- oder Distanzangriffen eine Chance, 'Läuternde Flammen' auszulösen. Verursacht sofort 178 Schaden und erhöht 5 Sek. lang jeglichen Schaden gegen Dämonen um 10%.\n44 ( 44)\n\nBosse mythischer Dungeons von Warlords of Draenor" }
entries[133598] = { ["name"] = "Gereinigter Splitter des dritten Monds", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+ 16 Vielseitigkeit\nBenutzen: Erzeugt einen Schild, der 20 Sek. lang [(1 + Vielseitigkeit) * 1081 ] Schaden absorbiert. Der Schild ist um 100% stärker, wenn Euer Angreifer ein Dämon ist. (1 Min Abklingzeit)\n44 ( 44)\n\nBosse mythischer Dungeons von Warlords of Draenor" }
