entries[133641] = { ["name"] = "Auge von Skovald", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, einen Teufelsmeteor auf Euer Ziel herab zu beschwören, der ihm und allen Gegnern in der Nähe 63 Feuerschaden zufügt.\nVerkaufspreis:" }
entries[133642] = { ["name"] = "Horn der Ehre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nBenutzen: Stößt in das Horn, was Euren Primärwert für 30 Sek. um 13 erhöht. (2 Min Abklingzeit)\n\"Die stärksten Vrykul werden von Odyn in den Hallen der Tapferkeit erwartet, um Valarjar zu werden. Sie kämpfen ewig, glänzend und golden.\"\nVerkaufspreis:" }
entries[133644] = { ["name"] = "Andenken an Angerboda", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Eure Nahkampfangriffe haben eine Chance, 'Schreie der Toten' zu aktivieren. Dieser Effekt gewährt Euch für 8 Sek. eine zufällige Kampfverstärkung.\nVerkaufspreis:" }
entries[133645] = { ["name"] = "Fährmannslohn der Naglfar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Heilzauber haben eine Chance, einen Schild hervorzurufen, der für 15 Sek. die nächsten 41 erlittenen Schaden verhindert. Während der Schild besteht, wird das Ziel alle 3 Sek. um 10 Gesundheit geheilt.\nVerkaufspreis:" }
entries[133646] = { ["name"] = "Partikel der Weihe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Strahlt eine Lichtexplosion aus, die bis zu 5 verletzte Verbündete innerhalb von 20 Metern um 184 Gesundheit heilt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[133647] = { ["name"] = "Gabe des Glanzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4 [Beweglichkeit oder Stärke]\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Durchbohrt Euer Ziel mit einem Lichtspeer, der 85 Heiligschaden verursacht. (1 Min Abklingzeit)\nVerkaufspreis:" }
