entries[133701] = { ["name"] = "Skrogzehennagel", ["text"] = "Einzigartig\nDas Tragen des Zehennagels kann Murlocs anlocken.\nBenötigt den Ruf 'Freund' bei Ilyssia von den Wassern.\n\"Obwohl er aus dem Meer kommt, strömt dieser Zehennagel einen starken Geruch aus. Nützlich beim Angeln in Azsuna.\"\nVerkaufspreis:" }
entries[133702] = { ["name"] = "Aromatischer Murlocschleim", ["text"] = "Einzigartig\nBenutzen: Reibt den Schleim auf Euren Körper, um seltene Fische anzulocken.\n\"Nützlich beim Angeln in Azsuna.\"\nVerkaufspreis:" }
entries[133703] = { ["name"] = "Perlmuttmuschel", ["text"] = "Einzigartig\nBenutzen: Hakt die Muschel an Eurer Angel fest, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Ilyssia von den Wassern.\n\"Nützlich beim Angeln in Azsuna.\"\nVerkaufspreis:" }
entries[133704] = { ["name"] = "Rostige Königinnenfischbrosche", ["text"] = "Einzigartig\nBenutzen: Legt die Brosche an, die es Euch in Azsuna gestattet, Schwärme geisterhafter Königinnenfische zu sehen.\nBenötigt den Ruf 'Guter Freund' bei Ilyssia von den Wassern.\n\"Ein uraltes Schmuckstück der Hochgeborenen, das wie ein Fisch geformt ist. Nützlich beim Angeln in Azsuna.\"\nVerkaufspreis:" }
entries[133705] = { ["name"] = "Verweste Fischgräte", ["text"] = "Einzigartig\nBenutzen: Wirft die Fischgräten weg.\nBenötigt den Ruf 'Freund' bei Hüterin Raynae.\n\"Völlig ungenießbar. Nützlich beim Angeln in Val'sharah.\"\nVerkaufspreis:" }
entries[133706] = { ["name"] = "Mooskiemenköder", ["text"] = "Einzigartig\nBenutzen: Gewährt eine Chance, seltene Fische anzulocken.\n\"Nützlich beim Angeln in Val'sharah.\"\nVerkaufspreis:" }
entries[133707] = { ["name"] = "Alptraumnachtkriecher", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Hüterin Raynae.\n\"Nützlich beim Angeln in Val'sharah.\"\nVerkaufspreis:" }
entries[133708] = { ["name"] = "Ertrunkener Distelblattwaldgeist", ["text"] = "Einzigartig\nBenutzen: Bettet den Distelblattwaldgeist zu angemessener Ruhe.\nBenötigt den Ruf 'Guter Freund' bei Hüterin Raynae.\n\"Der aufgedunsene Körper eines Waldgeistes. Nützlich beim Angeln in Val'sharah.\"\nVerkaufspreis:" }
entries[133709] = { ["name"] = "Abgefahrene Seeschnecke", ["text"] = "Einzigartig\nDas Tragen der Schnecke kann Drogbar anlocken.\nBenötigt den Ruf 'Guter Freund' bei Akule Flusshorn.\n\"Obwohl sie aus dem Meer kommt, strömt diese Schnecke einen starken Geruch aus. Nützlich beim Angeln am Hochberg.\"\nVerkaufspreis:" }
entries[133710] = { ["name"] = "Lachsköder", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\n\"Nützlich beim Angeln am Hochberg.\"\nVerkaufspreis:" }
entries[133711] = { ["name"] = "Geschwollenes Murlocei", ["text"] = "Einzigartig\nBenutzen: Bricht das Ei auf!\nBenötigt den Ruf 'Freund' bei Akule Flusshorn.\n\"Es wird bald schlüpfen.\"\nVerkaufspreis:" }
entries[133712] = { ["name"] = "Frostwurm", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Akule Flusshorn.\n\"Fühlt sich eiskalt an. Nützlich beim Angeln am Hochberg.\"\nVerkaufspreis:" }
entries[133713] = { ["name"] = "Elchhornhaken", ["text"] = "Einzigartig\nBenutzen: Befestigt den Haken an Eurer Angel, um seltene Köder zu fangen.\nBenötigt den Ruf 'Freund' bei Corbyn.\n\"Nützlich beim Angeln in Sturmheim.\"\nVerkaufspreis:" }
entries[133714] = { ["name"] = "Silberschuppenelritze", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\n\"Zu klein zum Essen, aber man kann sie als Köder nutzen. Nützlich beim Angeln in Sturmheim.\"\nVerkaufspreis:" }
entries[133715] = { ["name"] = "Uralter Vrykulring", ["text"] = "Einzigartig\nBenutzen: Streift den Ring über, der es Euch in Sturmheim gestattet, Oodelfjiskschwärme zu sehen.\nBenötigt den Ruf 'Hilfreicher Freund' bei Corbyn.\n\"Mit groben Darstellungen von Angeln verziert. Nützlich beim Angeln in Sturmheim.\"\nVerkaufspreis:" }
entries[133716] = { ["name"] = "Glitschige Drachenschuppe", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Corbyn.\n\"Eine kleine, schimmernde Sturmdrachenschuppe. Nützlich beim Angeln in Sturmheim.\"\nVerkaufspreis:" }
entries[133717] = { ["name"] = "Verzauberter Köder", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Sha'leth.\n\"Nützlich beim Angeln in Suramar.\"\nVerkaufspreis:" }
entries[133719] = { ["name"] = "Schlummernder Murloc", ["text"] = "Einzigartig\nBenutzen: Verpasst ihm eine Ohrfeige, um ihn aufzuwecken, dann lasst ihn gehen.\nBenötigt den Ruf 'Guter Freund' bei Sha'leth.\n\"Er hat einen langen Tag hinter sich.\"\nVerkaufspreis:" }
entries[133720] = { ["name"] = "Dämonenunrat", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\nBenötigt den Ruf 'Freund' bei Sha'leth.\n\"Nützlich beim Angeln in Suramar.\"\nVerkaufspreis:" }
entries[133721] = { ["name"] = "Bierflaschenpost", ["text"] = "Einzigartig\nBenötigt den Ruf 'Freund' bei Wichtlus.\n\"Beinhaltet eine Notiz: 'Hoffe, Ihr könnt das hier gebrauchen, Angler! - Nat'\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[133722] = { ["name"] = "Axtfischköder", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\n\"Nützlich beim Angeln in ozeanischen Gewässern der Verheerten Inseln.\"\nVerkaufspreis:" }
entries[133723] = { ["name"] = "Betäubter wütender Hai", ["text"] = "Einzigartig\nDauer: 1 min (Realzeit)\nBenutzen: Lässt den Hai frei. Vorsicht... er lebt noch!\nBenötigt den Ruf 'Freund' bei Wichtlus.\n\"Er ist noch nicht ganz tot, aber außerhalb des Wassers wird er nicht viel länger überleben.\"\nVerkaufspreis:" }
entries[133724] = { ["name"] = "Verwester Walspeck", ["text"] = "Einzigartig\nBenutzen: Platziert den verwesten Walspeck auf dem Boden, um Fliegen anzulocken.\nBenötigt den Ruf 'Guter Freund' bei Wichtlus.\n\"Riecht... nicht gut.\"\nVerkaufspreis:" }
entries[133725] = { ["name"] = "Leyschimmerkrötenfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Besonders scheu und schwer zu fangen.\"\nVerkaufspreis:" }
entries[133726] = { ["name"] = "Nar'thalassischer Einsiedler", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Diese Krabbe verbirgt sich tagsüber im Sand der Flüsse und Lagunen von Azsuna.\"\nVerkaufspreis:" }
entries[133727] = { ["name"] = "Geisterhafter Königinnenfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Ein Geist des Königinnenfisches, wie er vor zehntausend Jahren aussah.\"\nVerkaufspreis:" }
entries[133728] = { ["name"] = "Schreckensfinne", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Eine Perversion des Alptraums, der Val'sharah heimgesucht hat.\"\nVerkaufspreis:" }
entries[133729] = { ["name"] = "Dornenflunder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Von den Kiemen bis zur Flosse mit Stacheln übersäht.\"\nVerkaufspreis:" }
entries[133730] = { ["name"] = "Uralte Mooskieme", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"In den mondbeschienenen Gewässern von Val'sharah gedeihen die Mooskiemen besonders gut.\"\nVerkaufspreis:" }
entries[133731] = { ["name"] = "Bergkugelfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Sie werden von den Murlocs am Hochberg verehrt.\"\nVerkaufspreis:" }
entries[133732] = { ["name"] = "Kaltwasserkarpfen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Diese Spezies hasst warmes Wasser und bevorzugt die eisigen Gewässer des schneereichen Hochbergs.\"\nVerkaufspreis:" }
entries[133733] = { ["name"] = "Uralter Hochberglachs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Da die Drogbar gnadenlos Jagd auf Hochberglachse machen, werden sie selten so alt.\"\nVerkaufspreis:" }
entries[133734] = { ["name"] = "Oodelfjisk", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Der Oodelfjisk ist vor langer Zeit durch Überfischung ausgerottet worden.\"\nVerkaufspreis:" }
entries[133735] = { ["name"] = "Graubauchhummer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Wird von allem angelockt, was glänzt.\"\nVerkaufspreis:" }
entries[133736] = { ["name"] = "Donnernder Sturmrochen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Die größten Sturmrochen sind auch am tödlichsten.\"\nVerkaufspreis:" }
entries[133737] = { ["name"] = "Magieschluckerfrosch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Wie auch die Nachtgeborenen haben die Frösche Suramars einen unstillbaren Appetit auf Magie entwickelt.\"\nVerkaufspreis:" }
entries[133738] = { ["name"] = "Sehergratkugelfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Bei einigen Gelegenheiten wurden Murlocs dabei entdeckt, wie sie diese Fische als Waffen einsetzten.\"\nVerkaufspreis:" }
entries[133739] = { ["name"] = "Besudelter Runenschuppenkoi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Die Schuppen eines Fisches, doch das Herz eines Dämons. Nicht einmal die Fische sind sicher vor der Legion.\"\nVerkaufspreis:" }
entries[133740] = { ["name"] = "Axtfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Ähnlich einem Schwertfisch, aber mit geringerem Angriffstempo.\"\nVerkaufspreis:" }
entries[133741] = { ["name"] = "Seebodenkalmar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Nicht angelbar, da diese Tiere hunderte Meter tief unter der Meeresoberfläche leben. Diese Kalmare müssen mit... alternativen Methoden gefischt werden.\"\nVerkaufspreis:" }
entries[133742] = { ["name"] = "Uralter schwarzer Barrakuda", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser, wodurch sich Eure Angelfertigkeit der Verheerten Inseln um 5 erhöht. Funktioniert bis zu einem Maximum von 100.\n\"Vom berühmt-berüchtigten Walhai abgesehen, ist dies einer der größten Fische in den Meeren Azeroths.\"\nVerkaufspreis:" }
entries[133743] = { ["name"] = "Frisches Teufelsfleisch", ["text"] = "Questgegenstand\n\"Das durch teuflischen Einfluss verderbte Fleisch eines Teufelsfeuerbasilisken.\"" }
entries[133750] = { ["name"] = "Waffenkiste", ["text"] = "Questgegenstand\n\"Eine große Kiste, randvoll gefüllt mit Schusswaffen.\"" }
entries[133752] = { ["name"] = "Ausgebrannter Teufelshäscher", ["text"] = "Questgegenstand\n\"Eine beschädigter Teufelshäscherpanzer. Die meisten Extremitäten sind intakt.\"" }
entries[133753] = { ["name"] = "Arm eines Teufelshäschers", ["text"] = "Questgegenstand\n\"Ein abgetrennter Arm eines Teufelshäschers.\"" }
entries[133754] = { ["name"] = "Bein eines Teufelshäschers", ["text"] = "Questgegenstand\n\"Ein abgetrenntes Bein eines Teufelshäschers.\"" }
entries[133755] = { ["name"] = "Tiefenlichtangler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWerkzeug für Angeln\nAnlegen: Gewährt die Fähigkeit 'Unterströmung', mit der Ihr Euch sofort zum nächsten Fischschwarm der Legion im Umkreis von 100 Metern teleportieren könnt.\nAnlegen: +15 Angelfertigkeit.\nBenötigt Angeln (1)\nVerkaufspreis:" }
entries[133756] = { ["name"] = "Frischer Fleischhaufen", ["text"] = "Questgegenstand\nBenutzen: Platziert eine Opfergabe frischen Basiliskenfleisches auf dem Grimmschwingenaltar." }
entries[133760] = { ["name"] = "Blutverschmierte Notiz", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar der hastig hingekritzelten, verschmiert Wörter sind gerade noch lesbar.\"\n<Zum Lesen rechtsklicken>" }
entries[133761] = { ["name"] = "Flintlockes Kopfkanonenprototyp", ["text"] = "Questgegenstand\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab.\n\"Der Prototyp einer Schutzbrille mit angebrachten Schusswaffen. Äußerst praktisch und überhaupt nicht gefährlich.\"" }
entries[133762] = { ["name"] = "Relikt des Chaos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein unbekanntes Objekt, das eine alptraumhafte Energie verströmt.\"" }
entries[133763] = { ["name"] = "Schlüssel zu den Hallen", ["text"] = "Wird beim Aufheben gebunden\nEisen Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
