entries[133765] = { ["name"] = "Tapferkeitsumhang der Valarjar", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nVerkaufspreis:" }
