entries[133768] = { ["name"] = "Harbarons Fessel", ["text"] = "Wird beim Aufheben gebunden\nArkan Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[133769] = { ["name"] = "Getemperte Meeresgamaschen", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n10 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[133770] = { ["name"] = "Gurt des Stillwassers", ["text"] = "Wird beim Aufheben gebunden\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
