entries[133772] = { ["name"] = "Munitionskiste", ["text"] = "Questgegenstand\n\"Eine Kiste voller Kugeln.\"" }
entries[133775] = { ["name"] = "Schwarzpulverladungen", ["text"] = "Questgegenstand\nBenutzen: Tödlicher Sprengstoff, der bereit für Tests an der Flora Val'sharahs ist. (5 Sek. Abklingzeit)\n\"Ein Stapel Sprengladungen, die von Fargo Flintlocke hergestellt wurden. Hoffen wir, sie zerstören nicht gleich den ganzen Planeten.\"" }
entries[133780] = { ["name"] = "Teufelsfledermaushautfetzen", ["text"] = "Questgegenstand\n\"Sie strahlen ein widerlich grünes Leuchten aus.\"" }
entries[133782] = { ["name"] = "Sturmheimnadelschneckenhaus", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Ein röhrenförmiges Gehäuse, das an einem Ende spitz zuläuft.\"" }
entries[133791] = { ["name"] = "Murlocschmuckstück", ["text"] = "Questgegenstand\n\"Ein glänzendes Schmuckstück, hergestellt von einem Murloc.\"" }
entries[133793] = { ["name"] = "Teufelsfeuerrückgrat", ["text"] = "Questgegenstand\n\"Die Rückgrate behalten ihre Wärme noch lange bei, nachdem sie entfernt wurden.\"" }
entries[133794] = { ["name"] = "Didis grünes Feuerwerk", ["text"] = "Questgegenstand\n\"Didis ultraschnelles Saronittaschenfeuerwerk. Jetzt in grün.\"" }
entries[133795] = { ["name"] = "Unersättliche Fliege", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angel, um seltene Fische zu fangen.\n\"Nützlich beim Angeln in ozeanischen Gewässern der Verheerten Inseln.\"\nVerkaufspreis:" }
entries[133796] = { ["name"] = "Glyphe 'Erschreckende Metamorphose'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDurch Entfesseln der 'Metamorphose' fliehen Kleintiere in der Nähe in heller Panik.\nVerkaufspreis:" }
entries[133797] = { ["name"] = "Waffenpaketteile", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Verschiedene Teile des von Fargo getesteten Waffenpakets.\"" }
entries[133798] = { ["name"] = "Fass mit Schießpulver", ["text"] = "Questgegenstand" }
entries[133799] = { ["name"] = "Ingenieurskunstbaupläne", ["text"] = "Questgegenstand\n\"Ein Bauplan für eine Art von Pylon.\"" }
entries[133800] = { ["name"] = "Kordel von Maiev der Mondpriesterin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: 'Heilige Pein' hat eine Chance von 30%, die Abklingzeit von 'Sühne' abzuschließen. (Procchance: 30%)\n\"In einem längst vergessenen Leben heilte Maiev, Jägerin des Verräters, die Verwundeten und betete zur Mondgöttin.\"\nVerkaufspreis:" }
entries[133801] = { ["name"] = "Abzugprototyp", ["text"] = "Questgegenstand\n\"Nur leicht beschädigt...\"" }
entries[133802] = { ["name"] = "Runenstein der Vitalität", ["text"] = "Questgegenstand\n\"Ein uraltes Relikt, mächtig genug, um unbelebte Objekte zum Leben zu erwecken.\"" }
entries[133803] = { ["name"] = "Gewöhnliche Beutetasche", ["text"] = "Wird beim Aufheben gebunden\n\"Öffnet mich!\"\n<Zum Öffnen rechtsklicken>" }
entries[133804] = { ["name"] = "Verblichene Beutetasche", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[133805] = { ["name"] = "Kette des Donnerrufers", ["text"] = "Wird beim Aufheben gebunden\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[133806] = { ["name"] = "Arkaner Kompressor", ["text"] = "Questgegenstand\n\"Ein Mechanismus, der fast alle Explosionen eindämmen kann, damit sie nicht außer Kontrolle geraten.\"" }
entries[133807] = { ["name"] = "Emblem der Legion", ["text"] = "Questgegenstand\n\"Ein Emblem der Brennenden Legion, das die Rüstungen der Dämonen der Teufelsseele ziert.\"" }
entries[133808] = { ["name"] = "Preisgekrönte Rennschnecke", ["text"] = "Questgegenstand\n\"Glitschig!\"" }
entries[133810] = { ["name"] = "Rezept: Gesalzene Pfefferhaxe", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man gesalzene Pfefferhaxe zubereitet.\nBereitet eine gesalzene Pfefferhaxe zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nGesalzene Pfefferhaxe\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 kritischen Trefferwert.\nVerkaufspreis:\nBenötigt Magere Haxe (5), Grobes Meersalz (2), Dalapeñoschote (2)" }
entries[133812] = { ["name"] = "Rezept: Frittierte Mooskieme", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man frittierte Mooskieme zubereitet.\nBereitet eine frittierte Mooskieme zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nFrittierte Mooskieme\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Tempo.\nVerkaufspreis:\nBenötigt Mooskiemenbarsch (5), Moschushirschbutter (5)" }
