entries[133869] = { ["name"] = "Rezept: Herzhaftes Festmahl", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein herzhaftes Festmahl effizienter zubereitet.\nVerbraucht deutlich weniger Zutaten bei der Zubereitung von herzhaften Festmahlen.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nHerzhaftes Festmahl\nBenutzen: Richtet ein herzhaftes Festmahl her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 35 erhöht.\nVerkaufspreis:\nBenötigt Gesalzene Pfefferhaxe (3), Frittierte Mooskieme (3), Eingelegter Sturmrochen (3), Faronaarsprudel (3), Würziger Rippchenbraten (3), Speckstreifen (3)" }
entries[133870] = { ["name"] = "Rezept: Üppiges Festmahl von Suramar", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein üppiges Festmahl von Suramar effizienter zubereitet.\nVerbraucht deutlich weniger Zutaten bei der Zubereitung von üppigen Festmahlen von Suramar.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nÜppiges Festmahl von Suramar\nBenutzen: Richtet ein üppiges Festmahl von Suramar her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 46 erhöht.\nVerkaufspreis:\nBenötigt Grillrippchen à la Ley (3), Meeresschnitzel Suramar (3), Barrakuda à la Mrglgagh (3), Sturmrochen mit Koiaroma (3), Lachs Drogbar (3), Speckstreifen (3)" }
entries[133871] = { ["name"] = "Rezept: Knuspriger Speck", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man knusprigen Speck zubereitet.\nBereitet knusprigen Speck zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nKnuspriger Speck\nBenutzen: Esst etwas Speck!\n\nVerlängert den Bonus jedes Sättigungseffekts von den Verheerten Inseln um eine Stunde, bis zu einem Maximum von 6 Stunden.\nVerkaufspreis:\nBenötigt Speckstreifen (5), Dalapeñoschote (5)" }
entries[133872] = { ["name"] = "Rezept: Knuspriger Speck", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man knusprigen Speck effizienter zubereitet.\nStellt bei jeder Zubereitung zusätzlichen knusprigen Speck her.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nKnuspriger Speck\nBenutzen: Esst etwas Speck!\n\nVerlängert den Bonus jedes Sättigungseffekts von den Verheerten Inseln um eine Stunde, bis zu einem Maximum von 6 Stunden.\nVerkaufspreis:\nBenötigt Speckstreifen (5), Dalapeñoschote (5)" }
entries[133873] = { ["name"] = "Rezept: Knuspriger Speck", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man knusprigen Speck effizienter zubereitet.\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr knusprigen Speck her.\nBenötigt Kochkunst der Verheerten Inseln (1)\nVerkaufspreis:\nKnuspriger Speck\nBenutzen: Esst etwas Speck!\n\nVerlängert den Bonus jedes Sättigungseffekts von den Verheerten Inseln um eine Stunde, bis zu einem Maximum von 6 Stunden.\nVerkaufspreis:\nBenötigt Speckstreifen (5), Dalapeñoschote (5)" }
