entries[133958] = { ["name"] = "Geheimnisse der Leere", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 1.\nKlassen: Priester\n\"Als ich die Klinge berührte, erklang ein Name in meinem Verstand: Xal'atath. Ich wusste, dass ich den Dolch nicht vernichten konnte. Noch nicht. Wie kann man eine Macht bezwingen, die man nicht versteht?\"\nVerkaufspreis:" }
entries[133959] = { ["name"] = "Herz des Phönix", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 1.\nKlassen: Magier\n\"Als das Kämpfen ein Ende gefunden hatte, war Dath'Remar mit Dämonenblut bedeckt. Mit Einbruch der Nacht wurde uns klar, dass noch mehr Schlachten bevorstünden. Und dennoch, dieser Elf mit seiner Klinge gab uns Hoffnung, dass der Sieg in Reichweite lag.\"\nVerkaufspreis:" }
