entries[133968] = { ["name"] = "Siegel der Mondwache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Träger dieses gravierten Talismans haben sich als außergewöhnlich fähige Zauberer erwiesen.\"" }
entries[133970] = { ["name"] = "Reise der Zann'esu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: 'Hagel' erhöht den Schaden Eures nächsten Einsatzes von 'Blizzard' um 35%. Bis zu 5-mal stapelbar.\n\"Die Magier vom Klan der Zann'esu verließen ihr Heimatdorf Brunnhildar auf der Suche nach der perfekten Magie, um den Lichkönig zu besiegen. Sie kehrten nie zurück.\"\nVerkaufspreis:" }
entries[133971] = { ["name"] = "Zenk'aram, Iridis Anadem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Priester\nAnlegen: In Leerengestalt verursacht Ihr 3% mehr Zauberschaden und die Heilung von 'Vampirumarmung' wird um 250% erhöht.\n\"Dieses aus feinstem Teufelsstoff hergestellte Anadem gab Iridi die notwendige Kraft, um Dargonax zu besiegen.\"\nVerkaufspreis:" }
entries[133972] = { ["name"] = "Basiliskenfleisch", ["text"] = "Questgegenstand\n\"Das rohe Echsenfleisch ist zäh und giftig und muss vor dem Verzehr gekocht werden.\"" }
entries[133973] = { ["name"] = "Die schmerzhafte Berührung der Zwillinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Priester\nAnlegen: Bei Eurem ersten Einsatz von [ Gedankenstachel : 'Gedankenstachel' / 'Gedankenschinden'] in Leerengestalt springt 'Schattenwort: Schmerz' und 'Vampirberührung' auf 3 Gegner innerhalb von 10 Metern von Eurem Ziel über.\n\"Schluss mit diesen Kugeln, Fjola. Erledigen wir diese Herausforderer endlich. - Eydis Nachtbann\"\nVerkaufspreis:" }
entries[133974] = { ["name"] = "Lana'thels Wehklagen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\n+ 5 Vielseitigkeit\n\nPrismatischer Sockel\n\nKlassen: Todesritter\nAnlegen: Während Ihr Euch im Effektbereich Eurer Fähigkeit 'Tod und Verfall' befindet, ist Euer verursachter Schaden um 5% sowie Eure erhaltene Heilung um 5% erhöht.\n\"Lana'thel weinte bitterlich um die Leben ihrer elfischen Brüder und Schwestern, die sie auf ihrem Kriegszug nach Nordend zu verlieren erwartete. Dass sie selbst zahlreiche weitere Opfer fordern würde, wusste sie damals noch nicht.\"\nVerkaufspreis:" }
entries[133975] = { ["name"] = "Gnopettos Tagebuch", ["text"] = "Questgegenstand\n\"Der Großteil der Seiten ist verschmiert, aber manche Abschnitte sind dennoch gerade so lesbar.\"" }
entries[133976] = { ["name"] = "Cinidaria der Symbiont", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schurke , Mönch , Druide , Dämonenjäger\nAnlegen: Eure Angriffe fügen Gegnern mit mehr als 90% Gesundheit 30% zusätzlichen Schaden zu und heilen Euch um 100% des verursachten Schadens.\n\"Dieser dämonische Symbiont hat sich angepasst, um Kraft aus der Hitze des Gefechts zu schöpfen. Manchmal imitiert er sogar die Handlungen seines Wirtes.\"\nVerkaufspreis:" }
entries[133977] = { ["name"] = "Belo'virs letztes Gefecht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Stoff\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 200 / 200\nKlassen: Magier\nAnlegen: Nach dem Einsatz von [ Flimmern : 'Flimmern' / 'Blinzeln'] erhaltet Ihr 15 Sek. lang einen Absorptionsschild in Höhe von 20% Eurer maximalen Gesundheit.\n\"Die letzte Tat von Belo'vir Salonar, Großmagister von Quel'Thalas während des Dritten Krieges, bestand darin, Lady Liadrin an einen sicheren Ort zu teleportieren, als die Stadt fiel.\"\nVerkaufspreis:" }
entries[133978] = { ["name"] = "Teile eines stationären Kugelspenders", ["text"] = "Questgegenstand\nEinzigartig (15)\n\"Sie sind von Ranken ganz umschlungen und von den Dornen zerkratzt.\"" }
entries[133979] = { ["name"] = "Gegrillte Schnecke", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[133980] = { ["name"] = "Trübes Höhlenwasser", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 8000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[133981] = { ["name"] = "Rohe Höhlenschuppe", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[133983] = { ["name"] = "Mammutmilch", ["text"] = "Dauer: 1 tag\nBenutzen: Regeneriert 30 Min. lang alle 60 Sek. 50% der maximalen Gesundheit. (3 Sek. Abklingzeit)\n\"Warm und schaumig.\"\nVerkaufspreis:" }
entries[133984] = { ["name"] = "Nachtgeborenenverkleidung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Hüllt Euch in betörende Magie, um Euch die Erscheinung eines Nachtgeborenen zu geben.\n\nFunktioniert nur im Stadtbereich von Suramar.\n\"Ein Stapel Kleidung und anderer Dinge, die Euch helfen werden, Euch Eurer Umgebung anzupassen.\"" }
entries[133985] = { ["name"] = "Hochprozentiger Drog", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Desorientiert alle im ausgewählten Gebiet für 5 Sek.\nKann nur am Hochberg genutzt werden. (1 Min Abklingzeit)\n\"Warnung: Kann Blindheit verursachen.\"\nVerkaufspreis:" }
entries[133987] = { ["name"] = "Blauer Drog", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verzehren, um Euch blau zu färben. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[133988] = { ["name"] = "Drog für \"besondere Anlässe\"", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Zähflüssiger Schmodder, der nach Drogbarmaßstäben eine herrliche Erfrischung darstellt.\"\nVerkaufspreis:" }
entries[133989] = { ["name"] = "Selbstgemachter Drog", ["text"] = "Benutzen: Ein extrem starkes alkoholisches Getränk.\n\"Mehr eine Herausforderung als ein Getränk.\"\nVerkaufspreis:" }
entries[133990] = { ["name"] = "Trinkgefährte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen Trinkgefährten, der 5 Min. lang an Eurer Seite kämpft. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[133991] = { ["name"] = "Schellenschlüssel der Legion", ["text"] = "Questgegenstand" }
entries[133992] = { ["name"] = "DrogLeicht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Werdet leicht wie eine Feder.\nKann nur am Hochberg genutzt werden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[133993] = { ["name"] = "Krug Drog", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Angriffskraft und verringert die Trefferchance. Hält 1 Min. lang an.\nKann nur am Hochberg genutzt werden. (1 Min Abklingzeit)\n\"Werdet so richtig... Drogbar.\"\nVerkaufspreis:" }
entries[133996] = { ["name"] = "Bürgi Schwarzherzens Hübscher Hut", ["text"] = "Wird beim Aufheben gebunden\nKopf\nVerkaufspreis:" }
entries[133997] = { ["name"] = "Schwarzes Eis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Legt das schwarze Eis an, um mit Euren Abenteuern zu prahlen. (2 Min Abklingzeit)\n\"Wenn Ihr einen so großen schwarzen Diamanten tragt, wird man sicherlich auf Euch aufmerksam.\"\nVerkaufspreis:" }
entries[133998] = { ["name"] = "Regenbogengenerator", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Macht des Regenbogens! (10 Min Abklingzeit)" }
entries[133999] = { ["name"] = "Inaktiver Kristall", ["text"] = "Questgegenstand\nBenutzen: Überlädt Euer Ziel und lässt es große Mengen Mana ausstoßen. (8 Sek. Abklingzeit)\n\"Ein Gefäß, das große Mengen von Macht in sich aufnehmen kann.\"" }
entries[134001] = { ["name"] = "Prototyp A", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert mehrere Kleintiere in ein Rudel Eiszahnwölfe, um sie auseinanderzutreiben.\n\"Eine Waffe mit langem Lauf, die mit Prototypmunition geladen wurde. WARNUNG: Verwendung nur auf eigene Gefahr.\"" }
