entries[134003] = { ["name"] = "Prototyp B", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert mehrere Kleintiere in ein Rudel Eiszahnwölfe, um sie auseinanderzutreiben.\n\"Eine Waffe mit langem Lauf, die mit Prototypmunition geladen wurde. WARNUNG: Verwendung nur auf eigene Gefahr.\"" }
entries[134004] = { ["name"] = "Ewiges elitäres Elementiumsiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Steckt Euch den ewigen elitären Elementiumsiegelring auf den Finger. (30 Min Abklingzeit)\n\"Dieser exquisite Ring ist meisterlich aus den seltensten Materialien hergestellt und wird von der Schickeria gekauft, um ihn durch die Generationen weiterzuvererben.\"\nVerkaufspreis:" }
entries[134005] = { ["name"] = "Odyns Kessel", ["text"] = "Questgegenstand\n\"Uralte Runen zieren den riesigen Kessel.\"" }
entries[134006] = { ["name"] = "Düsters Reservebaumstamm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nBenutzen: Baumstammwurf. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[134007] = { ["name"] = "Ewiger schwarzer Diamantring", ["text"] = "Einzigartig anlegbar: Protzige schwarze Diamantringe (1)\nSpielzeug\nBenutzen: Legt den ewigen schwarzen Diamantring an, der von Generation zu Generation weitergegeben wurde.\n\"Dieser Ring erinnert sehr an den sagenumwobenen 'Schwarzes Eis' und wird über Generationen weitervererbt.\"\nVerkaufspreis:" }
entries[134008] = { ["name"] = "Einfacher Rosenkranz des Lichts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Betet zum Licht. Kann nicht im Kampf genutzt werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
