entries[134014] = { ["name"] = "Schattenblüte", ["text"] = "Questgegenstand\n\"Diese zarten Blüten enthalten ein starkes Toxin.\"" }
entries[134015] = { ["name"] = "Stinkender Fischkopf", ["text"] = "Questgegenstand\n\"Die Öle dieses Fisches werden für eine ganze Reihe alchemistischer Gebräue der Drogbar verwendet.\"" }
entries[134016] = { ["name"] = "Krug mit Floog", ["text"] = "Questgegenstand\n\"Diese Substanz zweifelhafter Herkunft ist für die Braubruls der Drogbar von großem Wert.\"" }
entries[134017] = { ["name"] = "Don Carlos' berühmter Hut", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n3 Rüstung\nAnlegen: Setzt Don Carlos' berühmten Hut auf und beschwört einen unkörperlichen Kojotengeist, der Euch begleitet. Der Geist wird an Eurer Seite bleiben, bis Ihr den Hut ablegt.\nBenutzen: Einen unkörperlichen Kojotengeist beschwören, der Euch begleitet. Der Geist wird an Eurer Seite bleiben, bis Ihr ihn fortschickt oder den Hut ablegt.\nVerkaufspreis:" }
entries[134019] = { ["name"] = "Don Carlos' berühmter Hut", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt Don Carlos' berühmten Hut auf und beschwört einen unkörperlichen Kojotengeist, der Euch begleitet. Der Geist wird an Eurer Seite bleiben, bis Ihr den Hut ablegt.\nVerkaufspreis:" }
