entries[134021] = { ["name"] = "Raketenhelm X-52", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schießt Euch zu den Sternen. Zur Sicherheit anderer wird empfohlen, die Startzone vor der Benutzung zu räumen. (5 Std. Abklingzeit)\nVerkaufspreis:" }
entries[134022] = { ["name"] = "Bürgi Schwarzherzens Hübscher Hut", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erliegt dem Fluch von Bürgi Schwarzherz. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[134023] = { ["name"] = "Abgefüllter Tornado", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lasst Euch hoch in die Lüfte Pandarias tragen. Kann nur im Freien verwendet werden. (2 Min Abklingzeit)\n\"Die Mantis haben vor langer Zeit gelernt, die Winde Pandarias ihrer Kaiserin gefügig zu machen.\"\nVerkaufspreis:" }
entries[134024] = { ["name"] = "Verfluchter Matrosenhelm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Verwandelt Euch in einen verfluchten Matrosen der Ho-zen und ermöglicht es Euch so, unter Wasser zu atmen und 200% schneller zu schwimmen.\n\nKann nur in Pandaria verwendet werden. (1 Stunde Abklingzeit)\n\"Hiermit werden niedere Matrosen zu willenlosen Ho-zen-Grobianen, die das Schreckensschiff Vazuvius rudern können.\"" }
entries[134026] = { ["name"] = "Ehrenbanner", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Repräsentiert Eure Fraktion! (2 Min Abklingzeit)\n\"Eure tapferen Taten erfüllen Eure Fraktion mit Stolz!\"" }
