entries[134048] = { ["name"] = "Leere Flasche Manawein", ["text"] = "\"Jeder Tropfen Mana wurde aus diesem Fläschchen gesaugt.\"\nVerkaufspreis:" }
entries[134049] = { ["name"] = "Überreste einer Mondwache", ["text"] = "\"Ein Lieblingssnack von Teufelsjägern, der bereits auf den Krieg der Ahnen zurückgeht.\"\nVerkaufspreis:" }
entries[134050] = { ["name"] = "Unverdauter Zahn", ["text"] = "\"Selbst das Verdauungssystem von Teufelsjägern hat seine Grenzen.\"\nVerkaufspreis:" }
entries[134051] = { ["name"] = "Halbverdaute Hearthstone-Karte", ["text"] = "\"Größtenteils noch immer brauchbar... riecht nur komisch, das ist alles.\"\nVerkaufspreis:" }
entries[134052] = { ["name"] = "Tierhalsband", ["text"] = "\"Die Inschrift lautet: 'Flauschie'.\"\nVerkaufspreis:" }
entries[134053] = { ["name"] = "Verlorene Schatzkarte", ["text"] = "\"Die Tinte scheint verschmiert zu sein. Bei genauerer Betrachtung stellt Ihr fest, dass es keine Tinte ist.\"\nVerkaufspreis:" }
entries[134054] = { ["name"] = "Unidentifizierte Hand", ["text"] = "\"Praktisch, wenn man mal Hand anlegen muss.\"\nVerkaufspreis:" }
