entries[134552] = { ["name"] = "Die Schreckensklingen", ["text"] = "Fügung\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schurke\n\"Keine Klinge kann so viel unschuldiges Blut vergießen, ohne auch einen Zoll von ihrem Träger einzufordern. Dies ist kein Schatz.\"\nVerkaufspreis:" }
